sys_script.script:
(function executeRule(current, previous) {

    var newStatus = current.getValue('booking_status');
    var oldStatus = previous.getValue('booking_status');

    // ========================================
    // CHECK-IN
    // ========================================
    if (newStatus == 'checked_in' && oldStatus != 'checked_in') {

        var log = new GlideRecord(
            'x_1958892_smart_0_parking_entry_log'
        );

        log.initialize();

        log.setValue(
            'booking',
            current.getUniqueValue()
        );

        log.setValue(
            'parking_slot',
            current.getValue('parking_slot')
        );

        // Record actual entry time
        var entryTime = new GlideDateTime();

        log.setValue(
            'entry_time',
            entryTime
        );

        log.setValue(
            'entry_verified_by',
            gs.getUserID()
        );

        if (!gs.nil(current.getValue('vehicle'))) {
            log.setValue(
                'vehicle',
                current.getValue('vehicle')
            );
        }

        log.setValue(
            'verification_status',
            'verified'
        );

        log.insert();
    }


    // ========================================
    // CHECK-OUT
    // ========================================
    if (newStatus == 'completed' && oldStatus != 'completed') {

        var existingLog = new GlideRecord(
            'x_1958892_smart_0_parking_entry_log'
        );

        existingLog.addQuery(
            'booking',
            current.getUniqueValue()
        );

        existingLog.orderByDesc('sys_created_on');
        existingLog.setLimit(1);
        existingLog.query();

        if (existingLog.next()) {

            var exitTime = new GlideDateTime();

            existingLog.setValue(
                'exit_time',
                exitTime
            );

            existingLog.setValue(
                'exit_verified_by',
                gs.getUserID()
            );

            existingLog.setValue(
                'verification_status',
                'completed'
            );

            existingLog.update();
        }
    }

})(current, previous);
